+// --- 4-pass 8-bit LSD radix sort, stable, ping-pong between a and b ---
+//   Each pass: count 256 digits, compute exclusive prefix sum, scatter
+//   backward (stable). If all elements share the same digit, skip pass.
+//   4 passes x 256 buckets = 1024 uint32 histogram = 4 KB.
+static void lsdradix_sort(uint32_t* a, uint32_t* b, size_t n) {
+    uint32_t cum[256];
+    uint32_t* src = a, * dst = b;
+    for (int pass = 0; pass < 4; ++pass) {
+        int shift = 8 * pass;
+        // Check if all elements have the same digit in this pass.
+        uint32_t d0 = (src[0] >> shift) & 0xFFu;
+        bool uniform = true;
+        for (size_t i = 1; i < n; ++i) {
+            if (((src[i] >> shift) & 0xFFu) != d0) { uniform = false; break; }
+        }
+        if (uniform) {
+            std::swap(src, dst);
+            continue;
+        }
+        for (size_t i = 0; i < 256; ++i) cum[i] = 0;
+        for (size_t i = 0; i < n; ++i) {
+            cum[(src[i] >> shift) & 0xFFu]++;
+        }
+        for (size_t i = 0; i < 255; ++i) cum[i + 1] += cum[i];
+        for (size_t i = n; i > 0; --i) {
+            uint32_t d = (src[i - 1] >> shift) & 0xFFu;
+            dst[--cum[d]] = src[i - 1];
+        }
+        std::swap(src, dst);
+    }
+    if (src != a) std::memcpy(a, src, n * sizeof(uint32_t));
+}
